import pathlib, os
roots=[pathlib.Path('/home'),pathlib.Path('/work'),pathlib.Path('/tmp'),pathlib.Path('/etc'),pathlib.Path('/opt')]
needle=b'SHOPIFY_API_SECRET'
found=[]
for root in roots:
    if not root.exists():
        continue
    for p in root.rglob('*'):
        try:
            if not p.is_file():
                continue
            if p.stat().st_size>2_000_000:
                continue
            data=p.read_bytes()
            if needle in data:
                found.append(str(p))
        except Exception:
            pass
print('\n'.join(found) if found else 'NO_MATCH')

